import json, os
NB=os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','..','notebooks','Lab18_Train_Churn_Model.ipynb')
_nb=json.load(open(NB))['cells']
def cell(prefix, max_lines=None):
    """Exact code of the code cell that follows the markdown cell starting with prefix."""
    for i,c in enumerate(_nb):
        if ''.join(c['source']).lstrip().startswith(prefix):
            src=''.join(_nb[i+1]['source']).rstrip()
            if max_lines and src.count('\n')+1>max_lines:
                src='\n'.join(src.split('\n')[:max_lines])+'\n...'
            return src
    raise KeyError(prefix)

